var bike = msg.payload || "all";
global.set("selectedBike", bike);
msg.payload = bike === "all" ? "All bicycles" : bike.replace("_", " ").toUpperCase();
return msg;

var p = msg.payload;

if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        node.warn("Invalid JSON");
        return null;
    }
}

if (!p || typeof p !== "object") {
    return null;
}

p.bike_id = p.bike_id || p.sensor_team || p.sensor_id;

if (!p.bike_id) {
    return null;
}

p.sensor_type = p.sensor_type || p.type;
p.timestamp = p.timestamp || new Date().toISOString();
p.timestampRegular = Number(p.timestampRegular || Date.now());
p.data = p.data || {};

msg.payload = p;
return msg;

var p = msg.payload;
var bike = p.bike_id;
var selected = global.get("selectedBike") || "all";
var states = flow.get("bikeStates") || {};

var s = states[bike] || {
    speed: 0,
    battery: 100,
    latitude: null,
    longitude: null,
    altitude: 0,
    acceleration: 0,
    parkingStatus: "Moving",
    locked: false,
    tripCount: 0,
    totalDistanceKm: 0,
    lastSeen: 0,
    lastLat: null,
    lastLon: null,
    parkingSince: null,
    gnssQuality: "Unknown",
    satellites: 0,
    hdop: null,
