var a = msg.payload || [];

if (!Array.isArray(a)) {
    msg.payload = {
        average: "N/A",
        maximum: "N/A",
        minimum: "N/A",
        samples: 0,
        tripDuration: "N/A",
        error: "msg.payload is not an array"
    };

    return msg;
}

var values = [];

for (var i = 0; i < a.length; i++) {
    var speed = Number(a[i].speed);

    if (isFinite(speed)) {
        values.push(speed);
    }
}

if (values.length === 0) {
    msg.payload = {
        average: "N/A",
        maximum: "N/A",
        minimum: "N/A",
        samples: 0,
        tripDuration: "N/A"
    };

    return msg;
}

var total = 0;

for (var j = 0; j < values.length; j++) {
    total += values[j];
}

var average = total / values.length;
var maximum = Math.max.apply(null, values);
var minimum = Math.min.apply(null, values);

var duration = 0;

if (a.length > 1) {
    var firstTime = new Date(a[0].timestamp).getTime();
    var lastTime = new Date(a[a.length - 1].timestamp).getTime();

    if (!isNaN(firstTime) && !isNaN(lastTime)) {
        duration = (lastTime - firstTime) / 60000;
    }
}

msg.payload = {
    average: average.toFixed(2),
    maximum: maximum.toFixed(2),
    minimum: minimum.toFixed(2),
    samples: values.length,
    tripDuration: duration.toFixed(1)
};

return msg;

var a = msg.payload || [];

var v = a
    .map(x => Number(x.battery))
    .filter(Number.isFinite);

if (!v.length) {
    msg.payload = {
        average: "N/A",
        minimum: "N/A",
        maximum: "N/A",
        lowEvents: 0
    };

    return msg;
}

msg.payload = {
    average: (
        v.reduce((x, y) => x + y, 0) / v.length
    ).toFixed(1),

    minimum: Math.min(...v).toFixed(1),

    maximum: Math.max(...v).toFixed(1),

    lowEvents: v.filter(x => x <= 20).length
};

return msg;

var a = msg.payload || [];

function r(v) {
    return v * Math.PI / 180;
}

function h(a, b, c, d) {
    var R = 6371000;

    var x = r(c - a);
    var y = r(d - b);

    var q =
        Math.sin(x / 2) ** 2 +
        Math.cos(r(a)) *
        Math.cos(r(c)) *
        Math.sin(y / 2) ** 2;

    return R * 2 * Math.atan2(Math.sqrt(q), Math.sqrt(1 - q));
}

var groups = {};
var total = 0;

a.forEach(function (x) {
    (groups[x.bike] = groups[x.bike] || []).push(x);
});

Object.keys(groups).forEach(function (k) {
    var g = groups[k];

    for (var i = 1; i < g.length; i++) {
        var d = h(
            g[i - 1].latitude,
            g[i - 1].longitude,
            g[i].latitude,
            g[i].longitude
        );

        if (d < 1000) {
            total += d;
        }
    }
});

msg.payload = {
    distanceKm: (total / 1000).toFixed(2),
    points: a.length,
    bicycles: Object.keys(groups).length,
    averageAltitude: a.length
        ? (
            a.reduce(function (s, x) {
                return s + Number(x.altitude || 0);
            }, 0) / a.length
        ).toFixed(1)
        : "N/A"
};

return msg;

var a = msg.payload || [];

var m = a
    .map(x => Math.sqrt(x.x * x.x + x.y * x.y + x.z * x.z))
    .filter(Number.isFinite);

if (!m.length) {
    msg.payload = {
        average: "N/A",
        maximum: "N/A",
        harshAcceleration: 0,
        harshBraking: 0,
        fallEvents: 0
    };

    return msg;
}

msg.payload = {
    average: (
        m.reduce((x, y) => x + y, 0) / m.length
    ).toFixed(2),

    maximum: Math.max(...m).toFixed(2),

    harshAcceleration: a.filter(x => x.x >= 2.5).length,

    harshBraking: a.filter(x => x.x <= -2.5).length,

    fallEvents: a.filter(x => x.tilt_angle > 60).length
};

return msg;

var a = msg.payload || [];

var parked = a.filter(function (x) {
    return String(x.status).toLowerCase() === "parked";
});

var byBike = {};

parked.forEach(function (x) {
    byBike[x.bike] = (byBike[x.bike] || 0) + 1;
});

var most = Object.keys(byBike)
    .sort(function (x, y) {
        return byBike[y] - byBike[x];
    })[0] || "N/A";

msg.payload = {
    parkingRecords: parked.length,
    totalRecords: a.length,
    lockedRecords: a.filter(function (x) {
        return String(x.locked) === "true";
    }).length,
    mostParkedBike: most
};

return msg;

msg.field = "speed";
